CAT = "corrRules"; SEG = "RUL"
# Applying written information in a correctional setting. Every rule belongs to a fictional
# facility written for this bank; the answer always comes from the rule given in the stem.
# Each item: (stem, key, [three wrong], explanation) or (stem, key, [four in order], expl, "fixed").
Q = [
("Rule: Officers count every inmate in a housing unit at 0600, 1200, 1700 and 2200. A count is not cleared until the count sheet matches the unit roster. Situation: At 1200, Officer Diaz counts 47 inmates; the roster lists 48. What must happen next?",
 "The count stays open", ["Lunch is served as planned", "Diaz signs the sheet at 47", "The 1700 count is moved up"],
 "The rule clears a count only when the sheet matches the roster. With 47 against 48, the count cannot be cleared, so it stays open until the difference is resolved."),
("Rule: A visitor may bring in only a clear plastic bag holding car keys, an ID card and up to $20 in coins for vending machines. Which visitor may enter with the bag?",
 "Ms. Park, keys, ID, $15 in coins", ["Mr. Hale, keys, ID and a phone", "Ms. Owen, ID and a $20 bill", "Mr. Tran, keys, ID, $25 in coins"],
 "Only coins up to $20 are allowed with keys and an ID. A phone and paper money are not on the list, and $25 is over the limit."),
("Rule: Inmates moving between buildings need a movement pass signed by a sergeant. A pass is good for 30 minutes from the time written on it. Situation: A pass reads 0910. At which time does it stop being valid?",
 "0940", ["0920", "0930", "1010"],
 "Thirty minutes after 0910 is 0940. After that the inmate needs a new pass.", ),
("Rule: Keys are issued only to staff on the key log. Keys may not leave the facility. Lost keys are reported to the shift commander at once. Situation: At the end of his shift Officer Grant finds a key ring in his jacket pocket in the parking lot. What should he do?",
 "Return it and tell the commander", ["Bring it back on his next shift", "Mail it to the key control office", "Give it to the next officer he sees"],
 "Keys may not leave the facility, and a key problem goes to the shift commander right away. Holding the keys until the next shift breaks both parts of the rule."),
("Rule: Each inmate may keep up to 6 books or magazines in the cell. Newspapers do not count toward the limit. Situation: During a cell check, which inmate is over the limit?",
 "Lowe: 5 books, 2 magazines", ["Banks: 4 books, 3 newspapers", "Cruz: 6 magazines, 1 newspaper", "Moss: 3 books, 3 magazines"],
 "Lowe has 7 books and magazines together. Banks has 4, Cruz has 6 and Moss has 6, since newspapers are not counted."),
("Rule: Any inmate who refuses a meal three meals in a row is reported to the medical unit. Situation: Inmate Rhee refused breakfast and lunch, ate dinner, then refused breakfast and lunch the next day. When is a report required?",
 "If he also refuses the next dinner", ["After the first breakfast refusal", "Now, since he refused four meals", "Only after two more refusals"],
 "The rule counts refusals in a row. Eating dinner broke the first run, so the second run reaches three only if he refuses the next dinner as well."),
("Rule: Officers must make a written log entry for every inmate movement, giving the inmate's name, number, destination and time out. Which entry meets the rule?",
 "1015 Ortiz 22-4417 to law library", ["1015 Ortiz to the library", "Ortiz 22-4417 to law library", "1015 22-4417 left the unit"],
 "Only the complete entry has the name, number, destination and time. Each of the others leaves out one of the four items."),
("Rule: Telephone calls last up to 15 minutes. An inmate on phone restriction may call only an attorney. Situation: Inmate Webb is on phone restriction and asks to call his sister. What should the officer do?",
 "Deny the call to his sister", ["Allow 15 minutes since it is family", "Allow a shorter call of 5 minutes", "Let him call if the sister agrees"],
 "A restricted inmate may call only an attorney. A family call is not allowed at any length."),
("Rule: When a fight starts, the officer calls a Code Blue on the radio, gives the location, and waits for responding staff before entering, unless a life is in danger. Situation: Two inmates are shoving in the dayroom; no one is hurt. What does the officer do first?",
 "Radio a Code Blue and the location", ["Step between the two inmates", "Order the dayroom locked down", "Write an incident report"],
 "The rule's first step is the radio call with the location. With no life in danger, the officer waits for help before going in."),
("Rule: Sharps such as razors are issued at 0700 and must be returned by 0730. A razor not returned by 0730 starts a unit search. Situation: At 0735, the sharps log shows 23 razors out and 22 back. What happens?",
 "A unit search begins", ["The razor is written off", "The inmate is given until noon", "Razors are not issued tomorrow"],
 "One razor is missing after 0730, which by the rule starts a search of the unit."),
("Rule: Inmates assigned to the kitchen report at 0430 and must pass a pat search when leaving. Situation: A kitchen worker asks to skip the search because he is late for a visit. What should the officer do?",
 "Search him before he leaves", ["Let him go and search him later", "Send him to the visit unsearched", "Have another worker vouch for him"],
 "The rule requires the search every time a kitchen worker leaves. Being late for a visit is not an exception."),
("Rule: Housing unit officers check each cell in the special watch area at least every 15 minutes and record the time of each check. Situation: The last check was at 2140. When is the next check due by?",
 "2155", ["2145", "2150", "2210"],
 "Fifteen minutes after 2140 is 2155. A check later than that breaks the rule.", ),
("Rule: Property taken from a new arrival is listed on a receipt. The arrival and the officer both sign it, and the arrival gets a copy. Situation: The arrival refuses to sign. Under the rule, what is missing?",
 "The arrival's signature", ["The officer's signature", "The list of property", "The arrival's copy"],
 "The rule needs both signatures. The officer signed and the property was listed, so the arrival's signature is the missing part."),
("Rule: Only inmates in work boots may enter the maintenance shop. Situation: Inmates Fox (sneakers), Gill (work boots), Hart (sandals) and Ives (shower shoes) arrive. Who may enter?",
 "Gill", ["Fox", "Hart", "Ives"],
 "Only work boots are allowed. Gill is the only one wearing them."),
("Rule: A visit ends at once if a visitor passes any item to an inmate. Situation: During a visit, a mother hands her son a folded photo. What should the officer do?",
 "End the visit", ["Keep the photo and let it go on", "Warn them and allow ten minutes", "Let him keep it if it is a photo"],
 "The rule ends the visit for any item passed, with no exception for photos."),
("Rule: Outside hospital trips need two officers. The inmate wears hand and leg restraints unless the doctor orders them removed for treatment. Situation: At the hospital, a doctor asks that the leg restraints come off for an X-ray. What is allowed?",
 "Remove the leg restraints", ["Remove all restraints", "Keep all restraints on", "Remove them and send one officer home"],
 "The rule allows removal when the doctor orders it for treatment, and only what the doctor asked for. Two officers stay on the trip."),
("Rule: Incoming mail is opened and inspected in the inmate's presence. Legal mail is opened in front of the inmate and checked only for contraband, not read. Situation: A letter arrives from a law office. What should the officer do?",
 "Open it before him without reading", ["Read it fully before handing it over", "Hold it until a lawyer calls", "Give it to him still sealed"],
 "Legal mail is opened in the inmate's presence and checked for contraband only. Reading it or handing it over sealed both break the rule."),
("Rule: Recreation is canceled if the outside temperature is below 20 degrees F or above 95 degrees F. Situation: On which reading does outdoor recreation go ahead?",
 "94 degrees F", ["18 degrees F", "96 degrees F", "101 degrees F"],
 "Recreation runs from 20 to 95 degrees. Only 94 is inside the range.", ),
("Rule: An officer relieving a post reads the post log, counts the inmates, and checks the equipment list before the off-going officer leaves. Situation: The relieving officer arrives late, and the off-going officer wants to leave at once. What should the relieving officer do?",
 "Finish the three checks first", ["Let the officer go and check later", "Check only the equipment list", "Count inmates after the officer leaves"],
 "All three steps come before the off-going officer leaves. Being late does not change the order."),
("Rule: Any staff member who finds contraband puts it in a sealed bag, labels it with the date, time, location and finder's name, and gives it to the shift sergeant. Situation: An officer finds a homemade knife in a mattress. Which step comes after sealing the bag?",
 "Label it with the details", ["Hand it to the inmate's lawyer", "Throw away the mattress", "Show it to the unit inmates"],
 "The rule's order is seal, label, then give it to the sergeant. Labeling is the next step after sealing."),
("Rule: Commissary orders may not exceed $40 a week, and no more than 5 of any one item may be bought. Which order is allowed?",
 "$38 total, 5 soups", ["$42 total, 3 soups", "$35 total, 6 soups", "$41 total, 5 soups"],
 "Only the $38 order with 5 soups stays within both limits. The others go over $40 or buy 6 of one item."),
("Rule: Laundry exchange is on Mondays and Thursdays. An inmate may exchange one uniform per exchange day. Situation: On a Thursday, an inmate asks to swap two uniforms. What is allowed?",
 "One uniform swap", ["Two uniform swaps", "No swap until Monday", "Two, if one is torn"],
 "Thursday is an exchange day, so one uniform can be swapped. The rule allows only one per day, with no exception for damage."),
("Rule: In a fire alarm, officers unlock cells only after the control center confirms the alarm is real. Situation: The alarm sounds, and inmates shout to be let out. The control center has not yet answered. What should the officer do?",
 "Wait for control to confirm", ["Unlock every cell at once", "Unlock only the nearest cells", "Silence the alarm himself"],
 "The rule ties unlocking to confirmation from the control center. Until control answers, cells stay locked."),
("Rule: Medication is given at the medication window. The officer checks each inmate's ID card before the nurse hands out medication. Situation: An inmate arrives without his ID card. What should the officer do?",
 "Not let the nurse give it yet", ["Let the nurse give it anyway", "Take another inmate's word", "Give him the medication himself"],
 "The ID check comes before medication is handed out. Without the card the check cannot be done, and officers do not hand out medication."),
("Rule: Tools are signed out on the tool board. Each tool's outline is covered by a numbered tag while it is out. At closing, every outline must be uncovered. Situation: At closing, outline 14 still has a tag on it. What does this mean?",
 "Tool 14 is still out", ["Tool 14 is back in place", "Tag 14 was lost", "The board needs a new outline"],
 "A covered outline means the tool is signed out. At closing that is a missing tool to account for."),
("Rule: Inmates in protective custody are escorted by one officer and kept apart from all other inmates during movement. Situation: A protective custody inmate needs to go to medical while a general population line is in the hall. What should the escort officer do?",
 "Wait until the hall is clear", ["Walk him behind the line", "Join the line and watch closely", "Ask a line inmate to escort him"],
 "Protective custody inmates are kept apart from all others during movement, so the escort waits for the hall to clear."),
("Rule: A new officer may work a post alone only after two training shifts on that post. Situation: Officer Lin has had training shifts in the gym twice and in the yard once. Where may she work alone?",
 "The gym only", ["The yard only", "Both posts", "Neither post"],
 "She has two training shifts in the gym but only one in the yard. The rule allows her to work alone in the gym only."),
("Rule: An inmate in a cell may have one blanket, one pillow and two sheets, plus a second blanket from November 1 to March 31. Situation: On April 10, which cell is over the limit?",
 "Kane: 2 blankets, 2 sheets", ["Ling: 1 blanket, 2 sheets", "Mora: 1 blanket, 1 pillow", "Nash: 1 pillow, 2 sheets"],
 "The second blanket is allowed only from November 1 to March 31. On April 10, Kane's two blankets are over the limit."),
("Rule: Officers write an incident report before the end of the shift in which the incident happened. Situation: An officer on the 0700 to 1500 shift stops a fight at 1450. By when is the report due?",
 "1500 that day", ["1700 that day", "0700 the next day", "Within 24 hours"],
 "The report is due before the shift ends, which is 1500. The other times run past the end of the shift.", ),
("Rule: An inmate may have visits from people on his approved visitor list only, up to 3 adults at a time. Children are not counted. Situation: Which group may visit together?",
 "3 listed adults and 2 children", ["4 listed adults", "2 listed adults and a family friend", "1 unlisted adult and a child"],
 "Up to 3 approved adults may visit, and children do not count. The other groups have too many adults or someone not on the list."),
("Rule: During a lockdown, all movement stops except medical emergencies, which need a sergeant's approval. Situation: During a lockdown, an inmate has chest pain. What is needed before he is moved?",
 "A sergeant's approval", ["A doctor's written order", "The end of the lockdown", "The warden's signature"],
 "A medical emergency may move during a lockdown, but only with a sergeant's approval."),
("Rule: Officers search each cell at least once a month. Cells are searched in the order on the search schedule unless a sergeant orders a cell searched out of order. Situation: A sergeant orders cell 12 searched today, but the schedule says cell 8 is next. What happens?",
 "Cell 12 is searched first", ["Cell 8 is searched first", "Neither is searched today", "Cell 12 waits until next month"],
 "A sergeant's order allows a search out of order. Cell 12 is searched as ordered, and the schedule goes on after."),
("Rule: Radios are checked at the start of each shift. A radio that fails is tagged and swapped before the officer goes to post. Situation: An officer's radio fails its check but she is needed on post now. What should she do?",
 "Swap it before going", ["Go now and swap it at lunch", "Borrow a radio from an inmate", "Go without a radio this once"],
 "The rule requires a failed radio to be swapped before going to post, even if the post is waiting."),
("Rule: Inmates may receive packages only in the two weeks after their birthday. Situation: Inmate Oyelaran's birthday is June 3. Which package date is accepted?",
 "June 14", ["May 30", "June 2", "June 20"],
 "The window runs from June 3 to June 17. Only June 14 falls inside it.", ),
("Rule: Officers do not accept gifts from inmates or their families. Any offer is written up. Situation: An inmate's wife offers the officer homemade cookies at the visiting desk. What should the officer do?",
 "Decline and write it up", ["Take them and share with staff", "Decline and say nothing more", "Accept them for the inmate"],
 "The rule bans the gift and requires a write-up of the offer. Declining without the write-up does only half of it."),
("Rule: If a count is wrong, officers recount. If the recount is also wrong, a census count is done by name and photo. Situation: The first count and the recount both show one inmate too many. What comes next?",
 "A census count by name and photo", ["A third count in the usual way", "Adding one to the roster", "Clearing the count as it is"],
 "Two wrong counts in a row move the officer to a census count, checking each inmate by name and photo."),
("Rule: Inmates may wear personal sweatshirts in the yard only if they are gray and have no writing. Situation: Which sweatshirt is allowed in the yard?",
 "Plain gray", ["Gray with a team logo", "Plain navy", "Black with a hood"],
 "The sweatshirt must be gray and have no writing. Only the plain gray one meets both conditions."),
("Rule: When an inmate is moved to another cell, the officer updates the unit board, the computer roster and the count sheet. Situation: An officer moved an inmate and updated the board and computer. What is left?",
 "The count sheet", ["The visitor list", "The property receipt", "The movement pass"],
 "The rule names three updates: board, computer roster and count sheet. Only the count sheet is left."),
("Rule: Staff assaulted by an inmate are seen by medical before writing any report. Situation: An inmate punches an officer, who is not visibly hurt and wants to write the report now. What should he do?",
 "Go to medical first", ["Write the report first", "Skip medical, as he looks fine", "Have a coworker write it"],
 "The rule puts the medical visit before any report, whether or not an injury shows."),
("Rule: Inmates in the law library may stay up to 2 hours, and up to 3 if a court date is within 7 days. Situation: Inmate Pruitt has a court date in 5 days. How long may he stay?",
 "3 hours", ["2 hours", "4 hours", "5 hours"],
 "His court date is within 7 days, so the longer limit of 3 hours applies.", ),
]
